SET statement_timeout='5s';SELECT jsonb_build_object('runs',(SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY run_id),'[]'::jsonb) FROM entry_plan_authority_runs_v1 r),'jobs',(SELECT coalesce(jsonb_agg(to_jsonb(j) ORDER BY run_id,job_key),'[]'::jsonb) FROM entry_plan_authority_jobs_v1 j),'events',(SELECT coalesce(jsonb_agg(to_jsonb(e) ORDER BY snapshot_id,event_ordinal),'[]'::jsonb) FROM opportunity_corporate_action_events_v3 e));